SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, STDDEV_SAMP(humidity) AS humidity_stddev, COUNT_IF(device_code = 'DV-02') AS dv_02_events, MIN(reading_ts) AS first_seen, COUNT_IF(device_code = 'DV-02') AS dv_02_events_2, SIZE(COLLECT_SET(device_code)) AS num_device_codes, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min FROM device_readings GROUP BY CUBE (DATE_TRUNC('DAY', reading_ts)) ORDER BY num_device_codes DESC
